SET LOCAL statement_timeout='15s';
DO $identity_sources_after$
DECLARE actual jsonb;qualified jsonb:=NULLIF(current_setting('ca.original_shaped_cash_statistics_qualification',true),'')::jsonb;BEGIN
 SELECT jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'kind',c.relkind,'persistence',c.relpersistence,'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))ORDER BY a.attnum)FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid),'validated',convalidated)ORDER BY conname COLLATE "C")FROM pg_constraint WHERE conrelid=c.oid),'indexes',(SELECT jsonb_agg(jsonb_build_object('definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'owner',pg_get_userbyid(ic.relowner))ORDER BY pg_get_indexdef(i.indexrelid)COLLATE "C")FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid AND i.indexrelid<>COALESCE(to_regclass('public.union_pnl_cash_outcomes_shape_gate_window'),0::oid)),'policies',(SELECT jsonb_agg(to_jsonb(p)ORDER BY p.oid)FROM pg_policy p WHERE p.polrelid=c.oid),'triggers',(SELECT jsonb_agg(contract ORDER BY (contract->>'name')COLLATE"C",(contract->>'function')COLLATE"C",(contract->'catalog'->>'tgtype')::integer)FROM(
 SELECT jsonb_build_object('name',regexp_replace(t.tgname,'RI_ConstraintTrigger_[ac]_[0-9]+','RI_ConstraintTrigger_OBJECT','g'),
 'catalog',to_jsonb(t)-ARRAY['oid','tgrelid','tgparentid','tgfoid','tgconstrrelid','tgconstrindid','tgconstraint','tgname'],
 'function',t.tgfoid::regprocedure::text,'constraint_definition',CASE WHEN t.tgconstraint=0 THEN NULL ELSE pg_get_constraintdef(t.tgconstraint)END,
 'definition',regexp_replace(pg_get_triggerdef(t.oid),'RI_ConstraintTrigger_[ac]_[0-9]+','RI_ConstraintTrigger_OBJECT','g'))AS contract
 FROM pg_trigger t WHERE t.tgrelid=c.oid)normalized)) INTO actual FROM pg_class c WHERE c.oid='public.union_pnl_cash_outcomes'::regclass;
 IF qualified IS NULL OR actual IS DISTINCT FROM qualified->'table'
 OR jsonb_build_object('relation',(SELECT to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relallfrozen','relfrozenxid','relminmxid'] FROM pg_class c WHERE c.oid='public.union_pnl_cash_outcomes'::regclass),'columns',(SELECT jsonb_agg(to_jsonb(a)ORDER BY a.attnum)FROM pg_attribute a WHERE a.attrelid='public.union_pnl_cash_outcomes'::regclass AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(to_jsonb(c)ORDER BY c.oid)FROM pg_constraint c WHERE c.conrelid='public.union_pnl_cash_outcomes'::regclass),'policies',(SELECT jsonb_agg(to_jsonb(p)ORDER BY p.oid)FROM pg_policy p WHERE p.polrelid='public.union_pnl_cash_outcomes'::regclass),'indexes',(SELECT jsonb_agg(jsonb_build_object('catalog',to_jsonb(i),'relation',to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relallfrozen','relfrozenxid','relminmxid'],'definition',pg_get_indexdef(i.indexrelid))ORDER BY i.indexrelid)FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid='public.union_pnl_cash_outcomes'::regclass)) IS DISTINCT FROM qualified->'schema_metadata'
 OR (SELECT jsonb_agg(jsonb_build_object('catalog',to_jsonb(t),'definition',pg_get_triggerdef(t.oid))ORDER BY t.oid)FROM pg_trigger t WHERE t.tgrelid='public.union_pnl_cash_outcomes'::regclass) IS DISTINCT FROM qualified->'raw_triggers'
 OR (SELECT jsonb_agg(jsonb_build_object('signature',s.signature,'definition',pg_get_functiondef(p.oid),'metadata',to_jsonb(p))ORDER BY s.signature COLLATE "C")FROM(VALUES('public.fn_accounting_tournament_week_quality(uuid,timestamp with time zone,timestamp with time zone)'),('public.fn_accounting_union_earned_plan_advance(uuid,timestamp with time zone,timestamp with time zone)'),('public.fn_club_weekly_accounting_summary(uuid)'),('public.fn_prepare_accounting_week(uuid,uuid,timestamp with time zone,timestamp with time zone)'),('public.fn_process_weekly_accounting_scope(uuid,uuid)'),('public.fn_rakeback_split_counts(uuid,timestamp with time zone,timestamp with time zone,timestamp with time zone,timestamp with time zone)'),('public.fn_union_pnl_evidence_report(uuid,timestamp with time zone,timestamp with time zone)'),('public.fn_weekly_close_first_visits_pending()'),('smarter_private.original_inventory_basis_generation()'),('smarter_private.original_inventory_proof_sources_match()'),('smarter_private.weekly_hand_parts_read(uuid,timestamp with time zone,timestamp with time zone,text,boolean)'),('smarter_private.weekly_hand_parts_reduce(uuid,timestamp with time zone,timestamp with time zone,boolean)'),('smarter_private.weekly_hand_parts_witness(uuid,timestamp with time zone,timestamp with time zone,boolean)'),('public.fn_accounting_close_certificate(text,uuid,timestamp with time zone,timestamp with time zone)'),('public.fn_accounting_close_problem(text,uuid,timestamp with time zone,timestamp with time zone)'),('public.fn_accounting_close_proof_lifetime()'),('public.fn_union_pnl_projection_ready(text)'),('public.fn_union_pnl_satellite_seat_owner(uuid,uuid)'),('public.fn_union_pnl_touched_registrations(timestamp with time zone,timestamp with time zone,boolean)'),('public.fn_union_pnl_tournament_entry_club_of(text,numeric,uuid,uuid,uuid,jsonb)'),('smarter_private.inventory_basis_cache_read(text,boolean,text,uuid,timestamp with time zone,timestamp with time zone)'),('public.fn_union_pnl_inventory_immutable()'),('public.fn_union_pnl_week_shaped_hands(uuid,timestamp with time zone,timestamp with time zone,boolean)'),('public.fn_union_pnl_cash_outcome_touch()'),('public.fn_union_pnl_cash_outcome_touch_row(uuid,bigint,timestamp with time zone,jsonb,jsonb)'),('public.fn_union_pnl_compact_participants(jsonb)'))s(signature)LEFT JOIN pg_proc p ON p.oid=to_regprocedure(s.signature)) IS DISTINCT FROM qualified->'function_authorities'
 OR smarter_private.original_inventory_proof_sources_match()IS DISTINCT FROM true
 OR smarter_private.original_inventory_basis_generation()IS DISTINCT FROM qualified->>'generation'
 OR pg_get_functiondef('smarter_private.original_inventory_proof_sources_match()'::regprocedure)IS DISTINCT FROM qualified->>'seal_definition'
 OR pg_get_functiondef('smarter_private.original_inventory_basis_generation()'::regprocedure)IS DISTINCT FROM qualified->>'generation_definition'
 THEN RAISE EXCEPTION 'original_shaped_cash_statistics_original_authority_changed';END IF;
 IF public.fn_ca_break_window_refuses_migrations(clock_timestamp())IS NOT NULL OR public.fn_platform_frozen()IS DISTINCT FROM false OR public.fn_active_maintenance_release_boundary()IS NOT NULL THEN RAISE EXCEPTION 'original_shaped_cash_statistics_window_refused';END IF;
 IF NOT EXISTS(SELECT FROM pg_statistic st WHERE st.starelid='public.union_pnl_cash_outcomes_shape_gate_window'::regclass AND st.staattnum=1 AND NOT st.stainherit AND st.stanullfrac=0 AND st.stadistinct=2 AND st.stakind1=1 AND array_length(st.stanumbers1,1)=2)THEN RAISE EXCEPTION 'original_shaped_cash_statistics_boolean_distribution_required';END IF;
END $identity_sources_after$;
SET LOCAL statement_timeout='15s';
COMMIT;
